node --input-type=module -e "
const base = '/private<tmp>/skim-eval-default-bug-timezone-dAvxJk/reminder-service/src/';
const { handle } = await import(base + 'api.js');
const { dueReminders } = await import(base + 'scheduler.js');
const { query } = await import(base + 'db.js');
handle({ method: 'POST', path: '/reminders', body: { userId: 'in', text: 'IST 09:00', at: '2026-03-01T09:00', tzOffsetMin: 330 } });
handle({ method: 'POST', path: '/reminders', body: { userId: 'utc', text: 'UTC 09:00', at: '2026-03-01T09:00', tzOffsetMin: 0 } });
const rows = query('SELECT * FROM reminders WHERE sent = 0');
for (const r of rows) {
  // find the first minute at which the scheduler considers it due
  let t = Date.parse('2026-02-28T00:00:00Z');
  while (dueReminders([r], t).length === 0) t += 60_000;
  console.log(r.text.padEnd(10), 'stored due_ms =', new Date(r.due_ms).toISOString(), '| scheduler fires at', new Date(t).toISOString());
}
"; cd /private<tmp>/skim-eval-default-bug-timezone-dAvxJk/reminder-service && node --test 2>&1 | tail -8
